import React, { useEffect, useState, useRef, useCallback } from "react";
import axios from "axios";
import Product from "./Product";
import "./ProductList.scss";

const ProductList = () => {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);
  const observer = useRef();

  const loadProducts = async (page) => {
    setLoading(true);
    try {
      const response = await axios.get(`/products.json?page=${page}&limit=10`);
      if (Array.isArray(response.data)) {
        setProducts((prevProducts) => [...prevProducts, ...response.data]);
        setHasMore(response.data.length > 0);
      } else {
        throw new Error("Dados inválidos: esperado um array de produtos");
      }
    } catch (error) {
      console.error("Erro ao carregar os produtos:", error);
      setError(error.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadProducts(page);
  }, [page]);

  const lastProductRef = useCallback(
    (node) => {
      if (loading) return;
      if (observer.current) observer.current.disconnect();

      observer.current = new IntersectionObserver((entries) => {
        if (entries[0].isIntersecting && hasMore) {
          setPage((prevPage) => prevPage + 1);
        }
      });

      if (node) observer.current.observe(node);
    },
    [loading, hasMore]
  );

  if (error) {
    return <div className="error">Erro: {error}</div>;
  }

  return (
    <div className="product-page">
      {/* Banner */}
      <div className="banner">
        <div className="banner-content">
          <h1>COURO</h1>
          <p>
            As peças de couro da ANIMALE são a interseção do clássico com inovação.
            Os shapes atemporais, detalhes únicos e variedade de materiais
            proporcionam um ajuste e acabamento que só quem tem um look couro
            sabe.
          </p>
          <div className="banner-links">
            <a href="#">VESTIDOS DE COURO</a>
            <a href="#">CALÇAS DE COURO</a>
            <a href="#">JAQUETAS DE COURO</a>
            <a href="#">COURO EM SALE</a>
          </div>
        </div>
      </div>

      {/* Filtros */}
      <div className="product-filters">
        <span>FILTRAR POR ▼</span>
        <span>ORDENAR POR ▼</span>
      </div>

      {/* Lista de Produtos */}
      <div className="product-list">
        {products.map((product, index) => {
          if (products.length === index + 1) {
            return (
              <div ref={lastProductRef} key={product.productId}>
                <Product product={product} />
              </div>
            );
          } else {
            return <Product key={product.productId} product={product} />;
          }
        })}
      </div>

      {loading && <div className="loading">Carregando...</div>}
      {!hasMore && <div className="no-more-products">Não há mais produtos.</div>}
    </div>
  );
};

export default ProductList;
